```html
<vl-toaster></vl-toaster>
<template id="melding-gelukt">
    <vl-alert type="success" icon="check" title="Gelukt" closable>
        <p>Wij hebben uw melding goed ontvangen en nemen deze spoedig in behandeling.</p>
    </vl-alert>
</template>
```

```js
const toaster = document.querySelector('vl-toaster');

// een eigen vl-alert uit een <template> buiten de toaster
const alert = document.querySelector('#melding-gelukt').content.cloneNode(true).querySelector('vl-alert');
toaster.show(alert); // of toaster.appendChild(alert), maar dan verdwijnt hij niet met fade-out

// of een vl-alert die de toaster zelf maakt
toaster.showAlert({ type: 'error', title: 'Fout', message: 'Dit is een foutmelding' });
```
